int32_t MAX_BERNOULLI = 64;

/**
* Computes the nth Bernoulli as a single-precision floating-point number.
*
* @param n    input value
* @return     output value
*
* @example
* float out = stdlib_base_bernoullif( 0 );
* // returns 1
*/
float stdlib_base_bernoullif( const int32_t n ) {
	if ( n < 0 ) {
		return STDLIB_CONSTANT_FLOAT32_NAN; // NaN
	}
	if ( n == 1 ) {
		return 0.5f;
	}
	if ( stdlib_base_is_oddf( n ) ) {
		return 0.0f;
	}
	if ( n > MAX_BERNOULLI ) {
		return ( ( n / 2 ) & 1 ) ? STDLIB_CONSTANT_FLOAT32_PINF : STDLIB_CONSTANT_FLOAT32_NINF;
	}
	return (float)bernoulli_value[ n / 2 ];
}
